globalThis.STORY_ZW_WORK_FR = {
  wealth: {
    '紫微': { title:"L’argent, garde rapprochée du trône", story:"Zi Wei dans le palais de la Richesse : l’argent suit votre position et votre réputation. Vous gagnez votre vie parce qu’on vous fait confiance et qu’on vous délègue des responsabilités, pas à la force du poignet. Vous dépensez avec goût, préférez acheter moins mais mieux, et payez parfois un peu plus pour sauver la face.", scenes:["Au dîner entre collègues, vous réglez souvent l’addition sans y penser, et c’est en regardant le relevé chez vous que ça pique un peu.","Pour un sac ou un appareil ménager, vous préférez attendre un mois de plus et prendre le modèle voulu plutôt qu’une copie bon marché."], advice:"Fixez chaque mois un « budget prestige » : une fois épuisé, on s’arrête, et le reste part automatiquement sur l’épargne le jour de la paie." },
    '紫微·天府': { title:"Un intendant assis entre deux coffres-forts", story:"Zi Wei et Tian Fu ensemble dans le palais de la Richesse : vous avez avec l’argent un calme naturel, vous savez conserver et aussi frapper au bon moment. Vos revenus viennent souvent d’un poste de direction ou d’une grande organisation, et plus c’est stable, plus vous accumulez. Le revers : trop de prudence, vous réfléchissez longtemps devant une occasion.", scenes:["Vous tenez peut-être un carnet de comptes depuis des années et retrouvez le mois où vous avez dépensé dix euros de trop.","Un ami vous propose d’ouvrir une boutique ensemble ; vous lui demandez d’abord six mois de chiffre d’affaires prévisionnel avant de dire oui."], advice:"Réservez chaque année un petit budget formation pour suivre un cours ou tester une compétence, afin que la prudence ne tourne pas à l’immobilisme." },
    '紫微·天相': { title:"L’argent rassurant, celui qui porte un tampon", story:"Zi Wei et Tian Xiang dans le palais de la Richesse : votre argent se porte mieux dans un cadre clair, avec contrat, fiche de paie et règles de partage nettes. Vous dépensez avec élégance et méthode, rarement sur un coup de tête, mais souvent pour les convenances et les obligations sociales. Quand d’autres partagent mal une note, vous êtes plus gêné qu’eux.", scenes:["En voyage entre amis, vous vous proposez comme trésorier et photographiez chaque dépense pour la noter dans un tableau partagé.","Cadeaux de mariage, collectes pour un départ ou un deuil : vous craignez toujours de donner trop peu, et sur un mois cela dépasse votre facture d’électricité."], advice:"Ouvrez un compte à part pour les dépenses sociales, fixez un plafond en début d’année, et au-delà, offrez de l’attention plutôt qu’un montant." },
    '紫微·破軍': { title:"Raser la vieille maison pour bâtir la neuve", story:"Zi Wei et Po Jun dans le palais de la Richesse : vos finances suivent un rythme de grandes ruptures, vous dépensez souvent d’abord pour déclencher la vague de revenus suivante. Vous osez miser sur une idée neuve et repartir de zéro ne vous fait pas peur. Le revers : de fortes variations, vous dépensez sans compter quand ça va, puis serrez les dents quand ça se resserre.", scenes:["Pour changer de métier, vous vous inscrivez d’un coup à trois formations, sans hésiter une seconde au moment de payer.","Lors d’un déménagement, vous remplacez tous les vieux meubles, et ce n’est qu’en fin de mois que vous voyez l’épargne fondre bien plus que prévu."], advice:"Avant toute grosse dépense, vérifiez qu’il reste trois mois de frais de vie sur le compte : que vos nouveaux départs reposent sur une base, pas sur la chance." },
    '紫微·七殺': { title:"Le butin rapporté de campagne", story:"Zi Wei et Qi Sha dans le palais de la Richesse : vous gagnez de l’argent avec élan, une fois l’objectif fixé vous voulez l’atteindre d’un coup, et la pression vous fait donner le meilleur. Ce qui compte pour vous, c’est de garder la main sur vos revenus ; vous n’aimez pas qu’on vous fixe un plafond. Vous dépensez avec décision, parfois trop vite.", scenes:["À peine les objectifs annuels annoncés, vous avez déjà classé dans votre tête les clients à appeler en premier.","Une voiture vous plaît, vous signez le jour de l’essai, et c’est sur la route du retour que vous calculez les mensualités."], advice:"Pour toute dépense supérieure à un mois de revenu, accordez-vous quarante-huit heures de recul avant de décider." },
    '紫微·貪狼': { title:"La coupe d’or qui circule au banquet", story:"Zi Wei et Tan Lang dans le palais de la Richesse : l’argent vous arrive souvent par le réseau, les rencontres et vos nombreux centres d’intérêt ; vous savez vous amuser et gagner. Vous avez du goût et aimez profiter : bonne table, voyages, art de vivre. Le revers : avec les sorties et les envies, l’argent file sans que vous le voyiez.", scenes:["À l’anniversaire d’un ami, vous rencontrez votre prochain partenaire de travail, et vous dépensez au passage la moitié de votre budget repas du mois.","Vous avez plusieurs passions, photo, dégustation de vin, travaux manuels, et pour chacune vous avez acheté l’équipement complet."], advice:"Ne financez qu’une passion par mois ; le reste va sur une liste d’envies, et vous verrez le mois suivant si l’envie est toujours là." },
    '天機': { title:"Une tête qui calcule plus vite que tout le monde", story:"Tian Ji dans le palais de la Richesse : vous gagnez votre vie avec votre tête et vos idées, vous comparez les prix, planifiez et imaginez souvent plusieurs sources de revenus. L’argent arrive avec souplesse et repart aussi vite, avec beaucoup de petits mouvements. {{B:天機:Vos plans sont clairs et efficaces, et votre épargne en profite.|Vous avez tendance à trop réfléchir et à tout modifier ; à force de changer de plan, l’argent ne reste pas.}}", scenes:["Pour un aspirateur, vous ouvrez dix onglets pour comparer les fiches techniques, puis attendez les soldes pour commander.","Vous avez déjà changé trois fois d’application de budget, persuadé à chaque fois que la suivante serait la bonne."], advice:"Choisissez une méthode d’épargne et tenez-la au moins six mois avant de la juger : mettez votre intelligence au service de la constance." },
    '天機·太陰': { title:"Un carnet de comptes tenu au clair de lune", story:"Tian Ji et Tai Yin dans le palais de la Richesse : votre argent vient surtout d’un salaire stable et de votre expertise, et s’accumule par petites touches attentives. Vous gérez finement, comptez juste, mais vous inquiétez facilement à force de trop penser. Au moindre changement de revenu ou de projet, vous voulez une sécurité de plus.", scenes:["Le jour de la paie, vous répartissez l’argent en plusieurs enveloppes : loyer, vie courante, fonds voyage.","Quand un ami change de poste avec une augmentation, vous pouvez passer la nuit à vous demander si vous ne devriez pas bouger aussi."], advice:"Fixez un « niveau de tranquillité » pour votre épargne : une fois atteint, autorisez-vous à vous inquiéter un peu moins." },
    '天機·巨門': { title:"L’argent gagné avec une tête et une langue", story:"Tian Ji et Ju Men dans le palais de la Richesse : vous excellez dans l’analyse et l’expression, et vous gagnez souvent votre vie par le savoir, l’explication et la négociation. Vous dépensez en exigeant, vous vous renseignez, vous questionnez, et les beaux discours vous touchent peu. Le revers : la méfiance, et des disputes pour des questions d’argent.", scenes:["En souscrivant une assurance, vous posez des questions jusqu’à ce que le conseiller sèche, puis lisez vous-même les conditions avant de décider.","Pour partager les charges, vous comptez au centime près ; votre colocataire vous trouve pointilleux et vous ne vous parlez plus pendant une semaine."], advice:"Avant de partager des frais avec quelqu’un, fixez les règles clairement et par écrit : vous vous épargnerez les discussions après coup." },
    '天機·天梁': { title:"Les conseils du stratège valent plus qu’un coffre", story:"Tian Ji et Tian Liang dans le palais de la Richesse : votre argent vient surtout de votre expertise et de vos conseils ; comme un stratège, vous résolvez les problèmes des autres grâce à votre expérience. Vous gérez avec prudence et savez planifier, mais vous aimez aussi conseiller les autres, et parfois vous mettez la main au portefeuille en plus.", scenes:["Un ami se demande s’il doit changer de logement ; vous passez la soirée à lui calculer son prêt, et il vous remercie d’un café.","Vous avez sans doute plusieurs livres sur l’argent, pleins de notes, dont vous n’appliquez qu’une ou deux idées."], advice:"Votre temps d’expert mérite d’être payé ; même entre proches, vous pouvez limiter le nombre ou la durée des consultations." },
    '太陽': { title:"Éclairer les autres d’abord, l’argent suit", story:"Tai Yang dans le palais de la Richesse : chez vous, la réputation et le bouche-à-oreille viennent souvent avant les revenus. Vous êtes généreux, aimez inviter et partager, et la joie des autres vous suffit. {{B:太陽:Vos sources de revenus sont claires et vous permettent de tenir votre rang.|Vous donnez souvent plus que vous ne récupérez, et votre main est plus rapide que votre portefeuille.}}", scenes:["Lors d’un achat groupé, c’est souvent vous qui avancez l’argent, et il y a toujours deux personnes qui oublient de vous rembourser.","Au repas d’équipe, vous réglez spontanément, et en fin de mois le relevé de carte a pris de l’épaisseur."], advice:"Fixez un plafond pour les sommes avancées et une date de remboursement : restez généreux tout en protégeant votre trésorerie." },
    '太陽·太陰': { title:"Une lumière le jour, une autre la nuit", story:"Tai Yang et Tai Yin, le Soleil et la Lune ensemble dans le palais de la Richesse : vos finances alternent ombre et lumière ; vous avez peut-être deux sources de revenus, ou des périodes d’aisance suivies de périodes serrées. Vous êtes tantôt large, tantôt économe, et vos émotions pèsent beaucoup sur vos achats. L’enjeu est de lisser ces variations.", scenes:["Vous travaillez peut-être en journée et prenez des missions ou tenez une boutique en ligne le soir : c’est avec les deux revenus que vous êtes rassuré.","De bonne humeur, vous offrez une boisson à tout le bureau ; de mauvaise humeur, vous vous refusez même un café."], advice:"Les bons mois, épargnez deux dixièmes de plus pour amortir les mois creux, et ne laissez pas l’humeur du jour décider de ce que vous dépensez." },
    '太陽·巨門': { title:"Transformer sa réputation en revenus par la voix", story:"Tai Yang et Ju Men dans le palais de la Richesse : vous gagnez votre vie par la parole ; enseignement, vente, communication et langues étrangères sont vos voies. Plus votre nom circule, plus vos revenus sont stables. Le revers : trop promettre, ou vous disputer pour de l’argent, ce qui abîme votre réputation.", scenes:["Une conférence ou une vidéo vous amène de nouveaux clients plus sûrement que cent cartes de visite.","Face à un client qui négocie, vous parlez trop franchement ; l’affaire se conclut, mais il ne revient jamais."], advice:"Avant de parler prix, notez trois chiffres plancher et tenez-vous-y, avec moins d’improvisation émotionnelle." },
    '太陽·天梁': { title:"La réputation d’abord, l’argent suit sans se presser", story:"Tai Yang et Tian Liang dans le palais de la Richesse : votre fortune se construit par le nom avant le gain, grâce à votre expertise, votre ancienneté et votre crédibilité, pas à la spéculation. Vous aimez aider et donnez souvent temps et argent pour les autres. Vos revenus sont généralement stables, mais n’explosent pas du jour au lendemain.", scenes:["C’est peut-être après l’obtention d’un diplôme ou d’une certification que vos revenus ont vraiment décollé : ce papier vaut plus que tous les discours.","Un jeune collègue dit être à court ; un « prends, tu me rendras » et l’argent est prêté, mais plus personne ne parle de la date de remboursement."], advice:"Avant de prêter, décidez du montant que vous pourriez perdre sans regret ; au-delà, refusez poliment." },
    '武曲': { title:"Un emploi solide forgé coup après coup", story:"Wu Qu est l’étoile de la richesse, et elle est à sa place dans le palais de la Richesse. Vous gagnez votre vie avec pragmatisme et décision, grâce à un vrai savoir-faire et à votre capacité d’exécution, et vous êtes très à l’aise avec les chiffres. Le revers : vous visez tellement l’efficacité que même avec vos proches, parler d’argent devient raide et l’ambiance se fige.", scenes:["Vous connaissez sans doute depuis longtemps vos dépenses fixes mensuelles, à la centaine près.","Votre conjoint veut une machine à café ; vous demandez « combien de fois par jour, et en combien de temps elle est rentabilisée ? », et l’ambiance retombe aussitôt."], advice:"Gardez dans votre budget un peu d’« argent plaisir » qui n’a pas à être rentabilisé, pour que l’argent achète aussi de la chaleur." },
    '武曲·天府': { title:"Un coffre-fort derrière une porte blindée", story:"Wu Qu et Tian Fu dans le palais de la Richesse : l’étoile de la richesse rencontre celle du trésor, vous savez naturellement gagner et conserver. Vos revenus penchent vers un salaire régulier, et épargner vous est aussi naturel que respirer. Le revers : la peur du risque, et vous rognez même sur ce que vous dépensez pour vous.", scenes:["Vous avez peut-être plusieurs comptes d’épargne, chacun avec un usage précis, sans jamais les mélanger.","En voyage, le budget suffit, mais vous prenez quand même la chambre la moins chère, et au retour vous trouvez que vous vous êtes un peu sacrifié."], advice:"Mettez de côté chaque année une somme pour vous faire plaisir, comme une prime de fin d’année pour toutes ces années de bonne garde." },
    '武曲·天相': { title:"Le tampon du comptable", story:"Wu Qu et Tian Xiang dans le palais de la Richesse : vous tenez à l’équilibre entre entrées et sorties et gérez votre argent comme les comptes d’une entreprise. Vos revenus viennent souvent d’un poste stable ou de services spécialisés, et vous gérez souvent aussi les finances de vos proches. Le revers : vous en faites tant pour les autres que vos propres projets restent en attente.", scenes:["Impôts, assurances, crédits de la famille : c’est vous qui vous en occupez, et vos parents vous demandent tout en premier.","Pour un cadeau commun entre amis, c’est toujours vous qui collectez, avancez et vérifiez, et à la fin il manque vingt euros."], advice:"Gardez une soirée par mois pour vos seuls comptes, et inscrivez d’abord vos propres objectifs d’épargne dans votre agenda." },
    '武曲·七殺': { title:"L’argent aiguisé sur le fil de la lame", story:"Wu Qu et Qi Sha dans le palais de la Richesse : vous gagnez votre vie par l’élan et le savoir-faire solide, vous acceptez les tâches dures et visez les gros gains. Vos revenus fluctuent souvent : parfois trop occupé pour dépenser, parfois obligé de puiser dans l’épargne. Vous dépensez franchement et achetez dès que vous êtes sûr.", scenes:["Certains mois de l’année, vous travaillez tard dans la nuit, mais quand la prime tombe, vous trouvez que ça valait la peine.","Quand un outil casse, vous ne le réparez pas : vous achetez directement le meilleur, pour ne pas perdre de temps, dites-vous."], advice:"Les bons mois, versez d’abord trois dixièmes sur un fonds d’urgence pour préparer les périodes creuses." },
    '武曲·破軍': { title:"L’or refondu sans cesse au creuset", story:"Wu Qu et Po Jun dans le palais de la Richesse : vos finances bougent beaucoup ; souvent vous gagnez et dépensez en même temps, ou investissez toute votre épargne dans une nouvelle direction. Vous avez de l’audace et n’avez pas peur de tout recommencer, mais l’argent s’use facilement d’un changement à l’autre.", scenes:["Pour changer de voie, vous dépensez peut-être d’un coup deux ans d’économies en matériel et en formations.","Votre téléphone a un an, une nouvelle fonction vous tente, et la revente de l’ancien ne rapporte presque rien."], advice:"Séparez votre argent en deux réserves, « le socle intouchable » et « l’argent pour recommencer », et ne tentez les nouvelles voies qu’avec la seconde." },
    '武曲·貪狼': { title:"Un arbre fruitier tardif mais robuste", story:"Wu Qu et Tan Lang dans le palais de la Richesse : votre fortune démarre lentement puis accélère ; jeune, vous trouvez souvent que l’argent manque, et c’est après avoir accumulé savoir-faire et relations que tout s’améliore. Vous savez profiter et négocier, et vous avez plus d’une source de revenus.", scenes:["À vingt-cinq ans, vous finissiez peut-être chaque mois à zéro ; après trente ans, vous découvrez que le réseau accumulé a doublé vos revenus.","Un repas entre amis, on discute, et la conversation débouche sur un projet commun."], advice:"Dès votre jeunesse, mettez de côté un dixième de chaque revenu mensuel, pour que la chance à venir ait de quoi grandir." },
    '天同': { title:"Un petit ruisseau qui coule sans se presser", story:"Tian Tong dans le palais de la Richesse : vous n’êtes pas avide, avoir assez vous suffit, et vous dépensez surtout pour une vie confortable. Vos finances passent souvent par une période d’efforts avant de se stabiliser. {{B:天同:Vous ne manquez de rien et il vous reste même de la marge.|L’argent arrive un peu plus lentement, et il vous faut planifier davantage par vous-même.}}", scenes:["Vous dépensez volontiers pour un bon matelas ou un canapé confortable, sans trop regarder le montant de votre épargne.","Vos amis parlent placements avec passion ; vous, vous pensez au café où aller ce week-end."], advice:"Programmez un virement automatique vers l’épargne le jour de la paie : épargner n’exige plus de volonté, et vous vivez toujours à votre aise." },
    '天同·太陰': { title:"Une tirelire sous un doux clair de lune", story:"Tian Tong et Tai Yin dans le palais de la Richesse : votre argent vient surtout d’un travail calme et stable, ou de domaines liés à l’esthétique, au service ou au soin. Vous dépensez au ressenti : ce qui est beau, confortable et chaleureux vous touche le plus. {{B:天同:Les petits ruisseaux finissent par faire une belle somme.|Vous dépensez facilement selon l’humeur, et votre épargne monte et descend.}}", scenes:["Un soir de pluie, vous flânez sur les boutiques en ligne et, sans trop savoir comment, achetez une bougie parfumée et deux plaids.","Vous avez une tirelire réservée aux voyages, et voir la somme grossir vous rassure."], advice:"Quand le moral est bas, laissez vos achats trois jours dans le panier avant de décider de valider." },
    '天同·巨門': { title:"Un thé amer d’abord, doux ensuite", story:"Tian Tong et Ju Men dans le palais de la Richesse : votre argent arrive souvent au prix d’efforts, de discussions et d’énergie, ou seulement une fois un malentendu dissipé. L’argent vous rend facilement anxieux : vous dites ne pas y tenir, mais vous comptez souvent en silence. Une fois la base constituée, la suite est plutôt bonne.", scenes:["Une mission terminée, vous devez parfois relancer plusieurs fois pour être payé, et chaque relance vous met mal à l’aise.","Vous vous disputez avec votre conjoint pour une petite dépense, et après coup vous comprenez que le vrai sujet était la sécurité."], advice:"Avant d’accepter une mission, inscrivez la date de paiement dans le contrat ou le message : relancer devient une règle, pas une question d’aplomb." },
    '天同·天梁': { title:"Un salaire sûr à l’ombre du grand arbre", story:"Tian Tong et Tian Liang dans le palais de la Richesse : vos finances penchent vers la stabilité, idéales pour un salaire fixe dans un cadre aux bons avantages. Vous préférez la qualité de vie à la grosse fortune, et dépensez souvent pour famille et amis. Le revers : vous vous satisfaites vite de la situation et ne réclamez pas les augmentations.", scenes:["Vous êtes peut-être dans la même entreprise depuis cinq ans, et les avantages de l’ancienneté vous retiennent.","Un ami est hospitalisé, vous lui faites un don sans discuter, quitte à moins manger dehors ce mois-là."], advice:"Une fois par an, parlez salaire et responsabilités avec votre responsable : la stabilité mérite aussi un juste prix." },
    '廉貞': { title:"Un portefeuille tiraillé entre règles et désirs", story:"Lian Zhen dans le palais de la Richesse : vous gagnez de l’argent avec des principes et savez entretenir des relations ; vos revenus viennent de votre expertise et de votre habileté relationnelle. Vous avez vos propres critères de dépense : avisé au quotidien, vous pouvez dépenser beaucoup d’un coup pour ce que vous aimez vraiment ou pour quelqu’un qui compte.", scenes:["Vous comparez le prix au rouleau du papier toilette, mais payez sans hésiter la pièce d’un créateur qui vous plaît.","Votre réseau professionnel vous apporte des missions, mais les cadeaux et dîners pour l’entretenir coûtent cher."], advice:"Faites des dépenses relationnelles un budget fixe, et vérifiez chaque trimestre quelles relations méritent qu’on continue à y investir." },
    '廉貞·天府': { title:"Un intendant avisé à la porte de la ville", story:"Lian Zhen et Tian Fu dans le palais de la Richesse : vous gérez avec finesse et sérieux, vous savez augmenter les recettes comme réduire les dépenses. Vos revenus viennent souvent de la gestion, de la planification ou d’un poste spécialisé ; ils s’accumulent sans hâte mais solidement. Vous dépensez avec méthode, parfois en comptant tellement que votre entourage le ressent.", scenes:["Vous avez peut-être mis les dépenses mensuelles du foyer dans un tableau, en tenant compte de l’écart de facture entre hiver et été.","Un ami propose un grand restaurant ; vous consultez d’abord la carte et les prix en ligne avant de décider quoi commander."], advice:"Gardez vos calculs pour les gros postes et laissez passer les petites sommes de temps en temps : la vie sera bien plus légère." },
    '廉貞·天相': { title:"Un argent mesuré qui suit les règles", story:"Lian Zhen et Tian Xiang dans le palais de la Richesse : vos finances se développent bien dans un cadre structuré, avec des revenus stables et des comptes clairs. Vous avez des principes : vous prenez sans gêne ce qui vous revient et ne touchez pas à ce qui ne vous revient pas. Le revers : un grand souci d’équité, et le moindre partage inégal vous reste en travers.", scenes:["Pour partager une prime entre collègues, vous proposez d’abord la règle de calcul, pour éviter les gênes après coup.","Quand on vous offre un cadeau de valeur, votre première pensée est : « que rendre pour ne rien devoir ? »"], advice:"Transformez l’équité en règle écrite, puis lâchez prise : inutile de tout recalculer dans votre tête à chaque fois." },
    '廉貞·七殺': { title:"Une route vers l’argent ouverte à la force des bras", story:"Lian Zhen et Qi Sha dans le palais de la Richesse : vous gagnez votre vie en vous battant seul, vous encaissez la difficulté et chaque échec vous rend plus déterminé. Vos revenus se gagnent à l’effort : les débuts sont durs, mais une fois le cap passé, l’accumulation est sérieuse. Les petites sommes vous importent peu, mais vous investissez tout dans les objectifs que vous vous fixez.", scenes:["Vous travaillez peut-être le jour et étudiez le soir, pour faire monter vos revenus marche après marche.","Pour vous offrir un équipement professionnel, vous acceptez de ne plus sortir pendant six mois."], advice:"Fixez plusieurs paliers d’épargne et célébrez un peu chacun : l’effort de long terme gagne à avoir un rythme." },
    '廉貞·破軍': { title:"Un atelier d’expériences qu’on démonte et rebâtit", story:"Lian Zhen et Po Jun dans le palais de la Richesse : vos finances changent beaucoup ; vous aimez les nouveautés et les nouvelles méthodes, et ces essais entraînent souvent des dépenses imprévues. Vous savez gagner de l’argent, mais le garder demande un entraînement délibéré. C’est quand l’émotion ou l’impulsion monte que les dépenses vous échappent le plus.", scenes:["Vous refaites peut-être toute la déco de votre chambre en une soirée, et ne voyez la notification bancaire que le lendemain.","Un ami vous propose une activité d’appoint ; vous vous lancez sans calculer les coûts et n’arrêtez qu’au bout de trois mois."], advice:"Un jour fixe par mois, passez en revue abonnements et paiements échelonnés, et résiliez le jour même ce qui ne sert plus." },
    '廉貞·貪狼': { title:"Un livre de comptes à la lumière des fêtes", story:"Lian Zhen et Tan Lang dans le palais de la Richesse : votre argent est souvent lié aux relations, aux loisirs et à l’esthétique ; vous êtes très sociable et savez utiliser l’argent pour entretenir vos liens. Vous aimez profiter : bonne table, tenues, soirées. Le revers : avec les envies qui se multiplient, l’argent s’écoule discrètement dans la fête.", scenes:["Deux soirées et un concert dans le même week-end : le lundi, vous n’osez pas trop ouvrir votre appli bancaire.","Plusieurs contrats ont été conclus autour d’un repas, mais c’est vous qui avez payé ces repas."], advice:"Avant chaque sortie, fixez un plafond de dépense et payez avec un moyen de paiement au montant limité." },
    '天府': { title:"Un grenier rempli de grain", story:"Tian Fu est l’étoile du trésor : dans le palais de la Richesse, il montre que vous savez garder votre argent, et ce qui entre dans votre poche n’en ressort pas facilement. Vous dépensez prudemment, privilégiez l’utile et la sécurité, et accumulez pas à pas. Le revers : à force de vouloir la stabilité, vous repoussez même les dépenses qui en valent la peine.", scenes:["Enfant, vous aviez une tirelire ; adulte, vous l’avez remplacée par un compte à terme, et regarder votre relevé vous apaise.","Vos collègues parlent de partir à l’étranger ; vous comparez encore quelle compagnie rapporte le plus de miles."], advice:"Chaque année, choisissez une dépense pour investir en vous-même, formation ou sport, pour que le grenier produise aussi quelque chose de neuf." },
    '太陰': { title:"Le clair de lune qui remplit la tirelire peu à peu", story:"Tai Yin est l’étoile de l’aisance : dans le palais de la Richesse, il annonce une fortune qui s’écoule en filet régulier ; vous êtes fait pour accumuler doucement, surtout pour l’épargne et le logement. Vous gérez avec soin, dépensez au ressenti et aimez les choses délicates. {{B:太陰:Vous accumulez de façon stable et abondante.|L’argent vous inquiète facilement : vous épargnez puis dépensez, puis regrettez.}}", scenes:["Vous avez peut-être un compte réservé à votre futur apport immobilier, alimenté discrètement chaque mois.","Une nuit d’insomnie, vous ouvrez un site marchand et ajoutez un à un à vos favoris les articles que vous n’osez pas acheter."], advice:"Écrivez vos objectifs de long terme en chiffres et en dates précis, et relisez-les quand l’angoisse monte : vous avancez." },
    '貪狼': { title:"Une fortune allumée au feu du désir", story:"Tan Lang dans le palais de la Richesse : vos sources de revenus sont variées, réseau, talents, vie sociale, et il arrive aussi des gains inattendus. Vous avez le don de profiter de la vie et dépensez volontiers pour les plaisirs et les passions. {{B:貪狼:Vous savez transformer vos passions en revenus.|Vous avez tendance à dépenser plus vite que vous ne gagnez.}}", scenes:["Parce que vous savez faire des cocktails, des amis vous demandent un coup de main pour un événement, et vous empochez un extra.","Devant une édition limitée, vous achetez dès l’ouverture des ventes, et vous vous rappelez ensuite que vous en avez déjà un chez vous."], advice:"Versez toujours la moitié de chaque gain inattendu sur l’épargne, et profitez de l’autre moitié." },
    '巨門': { title:"Une mine d’or creusée dans les mots", story:"Ju Men dans le palais de la Richesse : votre argent se gagne souvent par l’éloquence, l’expertise et la compétition ; plus vous expliquez clairement et analysez à fond, plus vous gagnez. Vous restez vigilant et ne croyez pas facilement aux recommandations. {{B:巨門:Vous savez faire de votre parole une source de revenus.|Veillez aux disputes autour de l’argent ; vos revenus vous semblent rarement assez rassurants.}}", scenes:["En réunion de devis, c’est souvent vous qui convainquez l’autre partie, et l’affaire se conclut sur place.","Un ami ne rembourse pas à temps ; vous prenez sur vous longtemps, puis, quand vous parlez enfin, les mots sont durs."], advice:"Gardez toujours une trace écrite des échanges d’argent : quand tout est clair, inutile de se disputer." },
    '天相': { title:"Une aisance digne, sans manquer de rien", story:"Tian Xiang dans le palais de la Richesse : vos finances sont stables, vous manquez rarement du nécessaire, et vos revenus viennent surtout d’un poste ou d’un service. Vous tenez à l’apparence et aux usages, et dépensez volontiers pour vos tenues et les obligations sociales. Vous êtes aussi facilement influencé : ce que vos amis achètent, vous finissez par le vouloir.", scenes:["Avant un mariage, vous achetez exprès une nouvelle tenue, c’est pour vous la moindre des politesses.","Des collègues organisent une commande groupée de soins ; vous n’en aviez pas l’intention, mais vous suivez."], advice:"Avant de suivre un achat groupé, demandez-vous : si personne ne me l’avait proposé, l’aurais-je acheté ?" },
    '天梁': { title:"L’ombre du vieil arbre n’est pas un arbre à billets", story:"Tian Liang dans le palais de la Richesse : votre argent se construit mieux lentement, par l’expertise, l’ancienneté et la crédibilité, pas dans la précipitation. Vous dépensez pour prendre soin des autres : aînés, plus jeunes, amis en difficulté, vous voulez aider. {{B:天梁:Des protecteurs vous apportent souvent des occasions.|L’argent arrive par à-coups, et votre bon cœur peut vous coûter cher.}}", scenes:["À une réunion de famille, un aîné vous demande d’aider financièrement un parent, et vous avez du mal à dire non.","Quelqu’un vous propose de gagner de l’argent vite ; d’instinct vous sentez que ça cloche, et la suite vous donne raison."], advice:"Avant d’aider, vérifiez que vos frais de vie et votre réserve ne sont pas touchés, puis décidez combien donner." },
    '七殺': { title:"Le butin gagné en solitaire", story:"Qi Sha dans le palais de la Richesse : vos finances ont un goût de sprint, vous gagnez par l’audace et l’action ; les débuts sont durs, mais une fois les bases posées, les revenus sont conséquents. Vous dépensez aussi avec décision, achetez quand vous êtes sûr et regardez rarement en arrière. Le revers : de fortes variations, et parfois un coup de panache qui coûte trop.", scenes:["Quand un gros projet arrive, vous vous y jetez entièrement, vos revenus doublent en trois mois, puis vient une période creuse.","Un scooter vous plaît, vous le commandez le jour même sans même hésiter sur la couleur."], advice:"Constituez au moins six mois de réserve de frais de vie, pour que chaque sprint se fasse l’esprit libre." },
    '破軍': { title:"De grandes marées qui entrent et sortent", story:"Po Jun dans le palais de la Richesse : votre argent entre et sort par grandes vagues, et vous dépensez sans retenue pour les nouveautés et les expériences. Vous avez un vrai sens de l’initiative pour gagner et trouvez souvent des occasions là où d’autres n’osent pas aller. Le revers : du mal à garder, l’argent vient vite et repart vite.", scenes:["À peine la prime de fin d’année reçue, vous l’avez convertie en un équipement photo complet.","Votre chambre contient plusieurs objets utilisés une ou deux fois, chacun ayant été à l’époque un « indispensable »."], advice:"Avant d’acheter du neuf, vendez ou donnez d’abord un objet ancien : la dépense aura une étape de plus à franchir." },
    '空': { title:"Un paysage emprunté par une pièce vide", story:"Le palais de la Richesse n’a pas d’étoile majeure : pour lire vos finances, on emprunte les étoiles du palais opposé, celui du Bien-être, et l’environnement et votre entourage comptent particulièrement. Entouré de personnes qui gèrent bien, vous épargnez ; entouré de dépensiers, vous dépensez aussi. L’avantage : une grande souplesse, vous pouvez ajuster votre façon de gagner à tout moment.", scenes:["Avec un colocataire économe, vous vous êtes mis sans y penser à apporter votre déjeuner.","Après un changement de poste et de structure de salaire, vos habitudes de consommation ont changé du tout au tout."], advice:"Fréquentez délibérément un ou deux amis à la gestion solide : laissez un bon environnement vous entraîner." }
  },
  career: {
    '紫微': { title:"Celui qui siège à la place d’honneur", story:"Zi Wei dans le palais de la Carrière : vous êtes fait pour une position de direction, doué pour coordonner l’ensemble et trancher en dernier. Vous tenez aux titres et au respect, et donnez le meilleur de vous dans un environnement avec une scène et de vrais pouvoirs. Le revers : du mal à descendre de votre piédestal et à entendre la voix du terrain.", fields:"Postes de direction, cadre dirigeant d’entreprise, responsable dans le secteur public, gestion de marque, création d’entreprise.", scenes:["Quand une réunion s’enlise, c’est souvent une phrase de vous qui tranche.","Quand on vous confie des photocopies ou la commande des repas, vous ne dites rien, mais vous trouvez qu’on gaspille votre talent."], advice:"Chaque mois, discutez avec un ou deux collègues de terrain : vos décisions gagneront en ancrage." },
    '紫微·天府': { title:"Un quartier général gardé par deux souverains", story:"Zi Wei et Tian Fu dans le palais de la Carrière : posé et doté d’envergure, vous excellez à gérer de vastes systèmes et ressources. Vous êtes fait pour gravir les échelons dans une grande organisation bien structurée, en privilégiant la stabilité à la vitesse. Le revers : trop de prudence, et un temps de retard face au changement.", fields:"Direction de grande entreprise, institutions financières, administration publique, services généraux, gestion d’actifs.", scenes:["Quand l’entreprise fusionne des services, c’est souvent à vous que la direction pense en premier pour piloter.","Un nouveau collègue propose une idée audacieuse ; votre premier réflexe est de demander où sont les risques."], advice:"Chaque année, testez vous-même une nouvelle façon de faire, pour que votre solidité ait aussi de l’élan." },
    '紫微·天相': { title:"Le grand intendant qui tient le sceau", story:"Zi Wei et Tian Xiang dans le palais de la Carrière : vous tenez aux règles, aux procédures et à l’équité, et excellez à coordonner les parties pour que tout fonctionne avec ordre. Vous êtes comme un poisson dans l’eau dans une organisation aux règles claires, souvent l’arbitre de confiance de vos collègues. Le revers : un grand souci de l’image et des règles qui vous rend raide face à l’imprévu.", fields:"Gestion administrative, juridique, ressources humaines, relations publiques, secrétariat général, gestion de la qualité.", scenes:["Deux services se disputent des ressources ; votre responsable vous demande d’arbitrer, et vous commencez par dresser un tableau des besoins de chacun.","Un collègue veut contourner la procédure ; vous lui dites tout net : « Ce n’est pas possible. »"], advice:"Laissez-vous un peu de marge pour improviser : la règle est un outil, pas un but." },
    '紫微·破軍': { title:"Le nouveau souverain qui rase la vieille ville", story:"Zi Wei et Po Jun dans le palais de la Carrière : vous êtes fait pour créer et réformer, et aimez démolir les vieux systèmes pour les reconstruire. Vous avez de la vision et du cran, et donnez le meilleur dans une structure en pleine transformation. Le revers : peu de patience, et dès que le système tourne, vous voulez le défi suivant.", fields:"Jeunes entreprises, réorganisation, développement de nouveaux produits, développement commercial, refonte de marque.", scenes:["Dès votre premier mois dans une entreprise, vous remettez à votre responsable une proposition pour revoir les processus.","Après deux ans de stabilité, vous vous ennuyez et ouvrez discrètement les sites d’offres d’emploi."], advice:"À chaque réforme, associez-vous à quelqu’un de doué pour l’exécution, pour que vos idées prennent vraiment corps." },
    '紫微·七殺': { title:"Le général qui part en campagne, sceau en main", story:"Zi Wei et Qi Sha dans le palais de la Carrière : vous agissez avec décision et cran, aimez tenir les commandes, et plus le défi est grand, plus vous êtes combatif. Vous êtes fait pour mener une équipe vers un objectif, avec une forte capacité d’exécution. Le revers : des exigences si hautes que votre équipe peut s’essouffler.", fields:"Direction commerciale, chef de projet, armée et police, création d’entreprise, direction des opérations.", scenes:["En fin de trimestre, vous emmenez l’équipe dans des heures supplémentaires d’affilée, et l’objectif est dépassé.","Un rapport ne vous convient pas, vous le renvoyez à refaire, et son auteur a discrètement les yeux rouges."], advice:"En donnant une consigne, ajoutez l’objectif et la raison : l’équipe vous suivra plus volontiers." },
    '紫微·貪狼': { title:"L’hôte le plus brillant de la salle de réception", story:"Zi Wei et Tan Lang dans le palais de la Carrière : polyvalent et sociable, vous êtes fait pour les métiers qui demandent réseau et goût. Vous concluez des affaires en société et excellez dans la mise en valeur et le marketing. Le revers : trop d’intérêts, une attention dispersée, ou une vie absorbée par les mondanités.", fields:"Relations publiques, marketing, industrie du divertissement, restauration, vente de luxe, organisation d’événements.", scenes:["À un cocktail professionnel, vous échangez vingt cartes de visite et concluez deux collaborations la semaine suivante.","Vous voulez à la fois lancer votre média, apprendre la mixologie et monter une activité annexe, et votre travail principal prend du retard."], advice:"Chaque trimestre, choisissez un seul objectif prioritaire à pousser à fond, et mettez les autres envies en attente." },
    '天機': { title:"Un engrenage toujours en mouvement", story:"Tian Ji dans le palais de la Carrière : vif d’esprit, vous excellez dans l’analyse, la planification et la résolution de problèmes, et préférez réfléchir plutôt que répéter les mêmes gestes. {{B:天機:Vos idées épargnent à l’équipe bien des détours.|Vous avez tendance à trop réfléchir et à modifier vos plans encore et encore.}} Vous changez aussi de poste plus souvent que d’autres.", fields:"Planification, développement logiciel, analyse de données, conseil, recherche, conseiller en appui.", scenes:["Votre responsable vous lance une demande floue, et en un après-midi vous dessinez les schémas de trois solutions.","Après un peu plus d’un an dans un poste, vous avez l’impression de ne plus rien apprendre et voulez changer d’air."], advice:"Avant de démissionner, listez trois choses que ce poste peut encore vous apprendre, et partez une fois apprises." },
    '天機·太陰': { title:"Un état-major éclairé au clair de lune", story:"Tian Ji et Tai Yin dans le palais de la Carrière : minutieux et bon planificateur, vous êtes fait pour la planification, la rédaction ou le rôle de conseiller au sein d’une structure stable. Vous êtes prudent et excellez dans les détails que les autres ne voient pas. Vos mutations ou changements de poste font aussi varier votre humeur.", fields:"Fonction publique, planification administrative, analyse financière, design, édition, éducation.", scenes:["Pour un grand événement, vous organisez le déroulé sans laisser passer le moindre détail.","Dès que la rumeur d’une réorganisation circule, vous êtes le premier à vous inquiéter pour votre poste."], advice:"Transformez vos inquiétudes en une liste concrète de plans B : l’anxiété devient de la préparation." },
    '天機·巨門': { title:"Le chercheur qui démonte les problèmes", story:"Tian Ji et Ju Men dans le palais de la Carrière : esprit de recherche et belle éloquence, vous excellez à analyser un problème et à l’expliquer clairement. Vous êtes fait pour les métiers très spécialisés qui exigent de la réflexion critique. Le revers : vous cherchez la petite bête, et votre parole tranchante crée vite des frictions avec les collègues.", fields:"Avocat, chercheur, enseignant, consultant, journaliste, formateur technique.", scenes:["Quand quelqu’un présente une solution en réunion, vous êtes le premier à voir la faille logique.","Votre critique est juste, mais trop directe, et le collègue qui a présenté reste maussade toute la journée."], advice:"Quand vous pointez un problème, proposez aussi une solution : votre esprit critique deviendra un atout pour l’équipe." },
    '天機·天梁': { title:"Le stratège qui élabore les plans sous la tente", story:"Tian Ji et Tian Liang dans le palais de la Carrière : vous excellez à concevoir des stratégies et à analyser les situations, fait pour être consultant ou conseiller. Vous avez une culture large, aimez conseiller et êtes souvent celui qu’on vient consulter. Le revers : beaucoup de paroles et peu d’actes, ou trop d’intérêt pour les affaires des autres.", fields:"Conseil en management, planification, santé, services spirituels et religieux, formation.", scenes:["Les collègues en difficulté viennent souvent vous voir, et la discussion dure une demi-heure.","Vous rédigez un rapport stratégique très complet, mais c’est quelqu’un d’autre qui le met en œuvre."], advice:"Choisissez une de vos propres recommandations et menez-la jusqu’au bout, pour qu’on voie votre capacité à concrétiser." },
    '太陽': { title:"Le projecteur qui éclaire toute la salle", story:"Tai Yang dans le palais de la Carrière : chaleureux et responsable, vous êtes fait pour les métiers face au public qui demandent de la crédibilité. {{B:太陽:Vous agissez au grand jour, et votre réputation vous vaut des promotions.|Vous travaillez souvent longtemps sans être remarqué.}} Vous aimez donner et prenez souvent trop sur vous.", fields:"Fonction publique, éducation, médias, politique, associations, commercial.", scenes:["Quand l’entreprise organise un événement, vous vous portez toujours volontaire pour animer ou coordonner.","Vous aidez un collègue à boucler son travail, et c’est à lui que revient le mérite."], advice:"Gardez une trace de ce que vous avez accompli et rendez-en compte de vous-même, pour que vos efforts soient vus." },
    '太陽·太陰': { title:"Deux emplois qui alternent jour et nuit", story:"Tai Yang et Tai Yin dans le palais de la Carrière : vous alliez l’élan extraverti et la finesse intérieure, et votre travail a une face lumineuse et une face discrète. Vous menez peut-être deux activités en parallèle, ou votre travail alterne jour et nuit. Le revers : une direction qui vacille, et deux fronts qui vous occupent.", fields:"Travail posté, médias, design, éducation, activité indépendante en parallèle, services.", scenes:["Vous travaillez en entreprise le jour et gérez votre compte sur les réseaux ou votre petite boutique le soir.","Un jour vous voulez foncer sur la vente, le lendemain passer en coulisses, et votre responsable ne sait plus ce que vous voulez."], advice:"Tous les six mois, comparez ce que vous investissez et ce que vous récoltez de chaque côté, et choisissez activement où mettre l’accent." },
    '太陽·巨門': { title:"La voix qui sort du haut-parleur", story:"Tai Yang et Ju Men dans le palais de la Carrière : éloquent et persuasif, vous êtes fait pour vivre de la parole et des métiers face au public. Vous êtes ouvert aux langues étrangères et aux autres cultures. Le revers : votre franchise, une phrase de trop peut créer des histoires.", fields:"Enseignant, formateur, avocat, médias, commercial dans une entreprise internationale, traducteur.", scenes:["Quand vous présentez sur scène, le public hoche la tête sans s’en rendre compte.","Une plainte lancée en passant dans un groupe de discussion se retrouve en capture d’écran chez votre responsable."], advice:"Avant de parler en public, marquez trois secondes de pause et demandez-vous si cette phrase peut être transférée sans problème." },
    '太陽·天梁': { title:"Le phare qui veille sur les navires de nuit", story:"Tai Yang et Tian Liang dans le palais de la Carrière : doté d’un sens de la justice et d’un vrai professionnalisme, vous êtes fait pour les grandes institutions ou le secteur public, où vous montez grâce à votre expertise et votre réputation. Vous aimez épauler les plus jeunes. Le revers : vous prenez la défense des autres et endossez des responsabilités qui ne sont pas les vôtres.", fields:"Fonction publique, santé, éducation, travail social, juridique, métiers à diplôme réglementé.", scenes:["Un nouveau se fait réprimander ; vous lui expliquez en privé comment ne plus refaire l’erreur.","Un collègue est traité injustement, vous prenez la parole, et vous voilà vous aussi dans le collimateur."], advice:"Avant d’intervenir, demandez à l’autre ce dont il a besoin : votre bienveillance aura plus de force." },
    '武曲': { title:"L’exécutant à la règle de fer", story:"Wu Qu dans le palais de la Carrière : pragmatique, décidé et attaché à l’efficacité, vous êtes très sensible aux chiffres et aux résultats. Vous êtes fait pour les métiers aux objectifs clairs qui exigent de l’exécution, et ce qu’on vous confie traîne rarement. Le revers : trop direct, un manque de souplesse relationnelle.", fields:"Finance, banque, comptabilité, ingénierie, armée et police, gestion industrielle.", scenes:["Un projet prend du retard ; vous listez l’avancement de chacun et rattrapez tout en une journée.","Des collègues trouvent votre ton trop dur, alors que vous pensez simplement dire les faits."], advice:"En confiant une tâche, ajoutez un mot de remerciement ou de reconnaissance : même efficacité, et une équipe plus coopérative." },
    '武曲·天府': { title:"L’intendant qui garde la porte du trésor", story:"Wu Qu et Tian Fu dans le palais de la Carrière : posé et respectueux des règles, vous excellez à gérer l’argent et les ressources. Vous êtes solide, fait pour vous investir longtemps dans une grande institution, et plus le temps passe, plus on compte sur vous. Le revers : trop de prudence, et vous bloquez souvent les nouvelles méthodes à l’entrée.", fields:"Banque, expertise comptable, direction financière, gestion d’actifs, assurance, finances publiques.", scenes:["Vous tenez le budget de l’entreprise : quiconque veut dépenser un euro de plus doit passer par vous.","Un collègue propose un nouveau logiciel ; vous demandez d’abord combien de temps l’ancien peut encore servir."], advice:"Chaque année, apprenez un nouvel outil ou une nouvelle compétence, pour grandir au sein même de la stabilité." },
    '武曲·天相': { title:"Le grand comptable qui gère les comptes et les gens", story:"Wu Qu et Tian Xiang dans le palais de la Carrière : vous excellez dans la finance et l’administration, travaillez avec rigueur et inspirez confiance. Vous êtes fait pour les métiers qui exigent intégrité et précision. Le revers : vous réparez souvent les erreurs des autres, au point de vous épuiser.", fields:"Comptabilité, administration financière, fiscalité, fonctionnaire, cadre bancaire, achats.", scenes:["Quand une note de frais bloque, c’est vous que tout le monde vient voir en premier.","Un collègue se trompe dans ses comptes ; vous râlez, mais vous corrigez en silence."], advice:"Apprenez à dire « cette partie, je vous laisse la faire » et gardez votre temps pour ce qui compte vraiment." },
    '武曲·七殺': { title:"La cavalerie de fer en première ligne", story:"Wu Qu et Qi Sha dans le palais de la Carrière : grande capacité d’action et résistance à la pression, vous êtes fait pour les métiers qui demandent du cran et de l’endurance. Vous allez droit au but, et plus c’est difficile, plus vous voulez gagner. Le revers : trop de hâte, et parfois l’affrontement frontal.", fields:"Armée et police, chirurgie, ingénierie, commercial, sport, métiers techniques et artisanaux.", scenes:["Un dossier difficile que d’autres ont refusé, vous l’acceptez sur-le-champ et le bouclez dans les délais.","En désaccord avec votre responsable, vous lui répondez sur le vif, et l’ambiance du bureau reste tendue plusieurs jours."], advice:"En cas de désaccord, commencez par « je comprends vos raisons », puis donnez votre avis : tout ira beaucoup mieux." },
    '武曲·破軍': { title:"La forge où l’on retrempe le métal", story:"Wu Qu et Po Jun dans le palais de la Carrière : vous avez l’esprit pionnier et un vrai savoir-faire technique, et aimez relever le défi de nouveaux domaines. Votre parcours connaît souvent de grands virages, et chaque changement vous apporte de nouvelles compétences. Le revers : peu de patience, vous changez facilement de direction à mi-chemin.", fields:"Développement technique, ingénierie, création d’entreprise, maintenance d’équipements, savoir-faire spécialisés, projets de transformation.", scenes:["Après quelques années de travail, vous vous reconvertissez peut-être soudain dans la programmation, et apprenez très vite.","À mi-parcours d’un projet, votre attention est déjà happée par une nouvelle occasion."], advice:"À chaque changement, rédigez une liste de clôture pour le poste précédent, afin d’emporter toute votre expérience." },
    '武曲·貪狼': { title:"Un sens des affaires qui brille à l’usage", story:"Wu Qu et Tan Lang dans le palais de la Carrière : vous avez le sens des affaires et l’habileté sociale, et êtes fait pour les métiers qui allient réseau et concret. Votre carrière se construit souvent dans l’ombre quand vous êtes jeune, puis brille à partir de la maturité. Le revers : de fortes envies, et la tentation de tout faire à la fois.", fields:"Commercial, finance, commerce international, restauration, industrie du divertissement, création d’entreprise.", scenes:["Après quelques années discrètes au service commercial, vous êtes un jour promu responsable régional.","Vous avez accepté trois activités annexes, et c’est votre travail principal qui ralentit."], advice:"Jeune, menez d’abord une expertise jusqu’à l’excellence, puis élargissez votre réseau." },
    '天同': { title:"Un petit atelier près de la source chaude", story:"Tian Tong dans le palais de la Carrière : de nature douce, vous aimez une ambiance de travail détendue et n’appréciez pas la compétition excessive. Vous êtes fait pour les métiers où l’on sert les autres et où l’on rend les gens heureux. {{B:天同:Dans un cadre agréable, vous tenez longtemps et avec régularité.|Faute de motivation, vous risquez de faire du surplace.}}", fields:"Services, restauration, tourisme, structures sociales, éducation des enfants, loisirs.", scenes:["Vous êtes celui qui met de l’ambiance au bureau ; les collègues qui ont un coup de blues viennent vous parler.","On vous confie un projet sous forte pression, et votre première pensée est de savoir si vous pouvez le refuser."], advice:"Fixez-vous un petit objectif annuel, pour que votre zone de confort ait elle aussi une courbe de progression." },
    '天同·太陰': { title:"Un atelier d’artisan sous la pluie fine", story:"Tian Tong et Tai Yin dans le palais de la Carrière : doux, délicat et doté d’un sens esthétique, vous êtes fait pour les métiers qui demandent patience et sensibilité. Vous aimez un environnement harmonieux et n’aimez pas le conflit. Le revers : vos émotions pèsent sur votre efficacité, un détail peut vous distraire une demi-journée.", fields:"Design, coiffure et esthétique, création artistique, métiers de l’écrit, action sociale, soins infirmiers.", scenes:["Les couleurs de vos présentations font toujours leur petit effet.","Une remarque anodine d’un collègue peut vous empêcher de vous concentrer tout l’après-midi."], advice:"Notez dans un journal de travail les émotions qui vous distraient : en repérant le schéma, vous pourrez prendre soin de vous plus tôt." },
    '天同·巨門': { title:"Le conteur dont la peine finit par payer", story:"Tian Tong et Ju Men dans le palais de la Carrière : éloquent et empathique, vous êtes fait pour les métiers de communication et d’explication. Votre carrière passe peut-être d’abord par une période difficile, mais la suite est solide. Le revers : vous êtes facilement entraîné dans les histoires de bureau ou dans le doute de vous-même.", fields:"Service client, vente, enseignement, accompagnement psychologique, restauration, interprétariat.", scenes:["À vos débuts, les clients vous mettaient souvent en difficulté ; trois ans plus tard, vous êtes l’interlocuteur en qui tout le monde a confiance.","Les rumeurs vont bon train au bureau, et vous y êtes mêlé alors que vous n’y avez pas pris part."], advice:"Restez cordial avec vos collègues mais gardez des limites : face aux commérages, restez bref et éloignez-vous." },
    '天同·天梁': { title:"Le grand arbre qui fait de l’ombre à tous", story:"Tian Tong et Tian Liang dans le palais de la Carrière : bon et stable, vous êtes fait pour les métiers du soin et du service, et pouvez durer longtemps au sein d’une institution. Vous aimez aider et avez votre propre rythme de travail. Le revers : un manque d’élan, et vous laissez souvent passer les promotions au profit des autres.", fields:"Fonction publique, santé, travail social, éducation, assurance, soins aux personnes âgées.", scenes:["Vous êtes dans le même hôpital ou la même école depuis des années, et les anciens disent qu’avec vous, ils sont tranquilles.","Une promotion se présente, vous la cédez à un collègue en pensant que ce n’est pas pour vous."], advice:"La prochaine fois qu’une occasion se présente, ne la refusez pas tout de suite : donnez-vous une chance d’essayer." },
    '廉貞': { title:"Celui qui danse au bord des règles", story:"Lian Zhen dans le palais de la Carrière : vous avez des principes tout en sachant vous adapter et entretenir vos relations ; vous êtes fait pour les métiers qui demandent à la fois habileté et expertise. Vous êtes ambitieux et exigeant envers vous-même. Le revers : un fort esprit de compétition, et sous la pression vous ressassez.", fields:"Relations publiques, juridique, politique, gestion administrative, électronique et technologie, techniques de précision.", scenes:["En réunion interservices, vous tenez compte de toutes les positions et finissez par dégager un consensus.","Une petite chose mal faite peut vous trotter dans la tête plusieurs jours."], advice:"Fixez-vous un critère du « suffisamment bien », et gardez votre énergie pour l’objectif suivant." },
    '廉貞·天府': { title:"Le grand intendant qui tient les positions", story:"Lian Zhen et Tian Fu dans le palais de la Carrière : avisé et posé, vous excellez en gestion et en planification, fait pour les métiers qui se construisent sur la durée. Vous travaillez avec méthode et veillez à l’efficacité de la répartition des ressources. Le revers : trop de prudence, et vous manquez parfois le meilleur moment.", fields:"Gestion administrative, planification financière, direction d’entreprise, gestion immobilière, administrations publiques.", scenes:["Le service dont vous avez la charge tient son budget au plus juste, année après année.","Une nouvelle occasion se présente, vous l’évaluez trop longtemps, et quelqu’un d’autre la saisit avant vous."], advice:"Fixez une échéance à chaque décision ; le moment venu, agissez selon le meilleur jugement du moment." },
    '廉貞·天相': { title:"Le poids sur la balance de la justice", story:"Lian Zhen et Tian Xiang dans le palais de la Carrière : vous tenez à l’équité et à l’ordre, excellez à concilier les intérêts dans le cadre des règles, et inspirez confiance. Vous êtes fait pour les métiers aux règles claires qui exigent de l’intégrité. Le revers : un attachement si fort aux principes qu’on vous trouve peu abordable.", fields:"Juridique, administration, ressources humaines, audit, fonction publique, gestion de la qualité.", scenes:["Un différend éclate dans l’entreprise, et on vous demande de servir d’intermédiaire.","Quelqu’un vous demande une petite faveur hors des règles ; vous refusez net, et il vous en veut depuis."], advice:"Quand vous tenez à vos principes, adoucissez le ton : votre équité sera mieux acceptée." },
    '廉貞·七殺': { title:"L’éclaireur qui taille sa route dans les ronces", story:"Lian Zhen et Qi Sha dans le palais de la Carrière : vous avez de l’audace et de la ténacité, fait pour les métiers où il faut se battre et partir de rien. Vous acceptez la difficulté, et plus c’est dur, plus vous êtes combatif. Le revers : trop solitaire, l’habitude de tout porter seul jusqu’au bout.", fields:"Développement commercial, ingénierie, armée et police, chirurgie, création d’entreprise, métiers techniques et artisanaux.", scenes:["L’entreprise s’attaque à un nouveau marché, et vous vous portez volontaire pour la zone la plus difficile.","Votre dossier est bloqué, mais vous ne demandez pas d’aide, jusqu’à ce que tout éclate au dernier moment."], advice:"Face à une difficulté, parlez-en tout de suite à quelqu’un : vous n’avez pas à livrer chaque bataille seul." },
    '廉貞·破軍': { title:"L’aventurier qui fait sauter les cadres", story:"Lian Zhen et Po Jun dans le palais de la Carrière : vous osez essayer et n’aimez pas les sentiers battus, fait pour les métiers changeants qui exigent de l’innovation. Votre carrière peut connaître de grands hauts et bas et de fréquents changements de voie. Le revers : l’impulsivité, vous sautez avant d’avoir fini de réfléchir.", fields:"Création d’entreprise, nouveaux médias, recherche et développement technologique, savoir-faire spécialisés, gestion de crise.", scenes:["Vous changez peut-être deux fois de poste en un an, et apprenez à chaque fois des compétences entièrement nouvelles.","Votre responsable dit « étudions d’abord la question », et vous avez déjà un premier prototype."], advice:"Avant d’agir, notez trois risques possibles et leurs parades : un filet de sécurité pour votre élan." },
    '廉貞·貪狼': { title:"La star sociale qui brille dans la foule", story:"Lian Zhen et Tan Lang dans le palais de la Carrière : très habile en société et polyvalent, vous êtes fait pour les métiers qui demandent charme et réseau. Vous êtes à l’aise en société et les clients aiment traiter avec vous. Le revers : beaucoup de mondanités, et le risque de vous laisser porter par les relations et les tentations.", fields:"Relations publiques, divertissement, restauration, beauté, commercial, organisation d’événements.", scenes:["Après un dîner, chaque client se souvient de votre nom.","Vous avez accepté trop d’invitations, et le rapport de votre travail principal ne cesse d’être repoussé."], advice:"Réservez chaque semaine des plages fixes de concentration, que vous ne sacrifiez à aucune sortie." },
    '天府': { title:"L’intendant qui protège toute la ville", story:"Tian Fu dans le palais de la Carrière : posé et fiable, vous excellez en gestion et en coordination, fait pour évoluer longtemps dans une organisation bien structurée. Vous travaillez avec ordre et n’aimez pas le risque. Le revers : à trop chercher la stabilité, les occasions de percer vous échappent.", fields:"Gestion administrative, finance, banque, administrations publiques, grandes entreprises.", scenes:["Les dossiers dont vous avez la charge sont toujours parfaitement rangés, un nouveau les comprend au premier coup d’œil.","On vous invite à rejoindre un nouveau projet ; vous réfléchissez longtemps et finissez par décliner."], advice:"Accordez-vous chaque année un petit quota d’audace : acceptez une mission hors de votre zone de confort." },
    '太陰': { title:"Un travail minutieux qui luit la nuit", story:"Tai Yin dans le palais de la Carrière : délicat et doux, vous excellez dans la planification et le soin du détail, fait pour les métiers stables qui demandent de la patience. {{B:太陰:Dans l’ombre, vous obtenez des résultats soignés et l’on vous fait pleinement confiance.|Les changements dans votre environnement de travail vous perturbent facilement.}}", fields:"Design, finance, immobilier, édition, soins infirmiers, secteurs tournés vers une clientèle féminine.", scenes:["Vos dossiers sont si complets que votre responsable n’a presque rien à corriger.","Pendant les mois de remaniements dans l’entreprise, vous dormiez souvent mal."], advice:"Séparez vos soucis en deux colonnes, ce que vous pouvez contrôler et ce que vous ne pouvez pas, et ne traitez que la première." },
    '貪狼': { title:"L’artiste aux multiples talents", story:"Tan Lang dans le palais de la Carrière : curieux de tout et rapide à apprendre, vous êtes fait pour les métiers qui demandent créativité, sens du contact et compétences variées. {{B:貪狼:Vous savez transformer vos talents en carrière.|Vous risquez de tout savoir un peu sans rien maîtriser vraiment.}} Vous brillez facilement au milieu des autres.", fields:"Commercial, divertissement, marketing, restauration, beauté, enseignement artistique.", scenes:["À la fête de fin d’année, vos collègues vous poussent toujours sur scène.","Vous avez appris la photo, le graphisme et le montage, vous savez tout faire, mais votre CV n’a pas de fil conducteur."], advice:"Choisissez la compétence que vous préférez et approfondissez-la trois ans, pour qu’elle devienne votre signature." },
    '巨門': { title:"L’expert qui s’impose par la parole", story:"Ju Men dans le palais de la Carrière : doué pour l’analyse et l’expression, vous aimez aller au fond des choses, fait pour vivre de votre éloquence ou de votre expertise. {{B:巨門:Votre parole vous suffit pour bâtir votre réputation.|Veillez aux histoires que vos paroles peuvent provoquer.}}", fields:"Avocat, enseignant, formateur, commercial, chercheur, médias.", scenes:["En réunion, vous soulevez un problème que tout le monde avait négligé, et votre responsable vous voit d’un autre œil.","Une plaisanterie est mal comprise par un collègue, et il vous faut une semaine pour dissiper le malentendu."], advice:"Confirmez par écrit tout ce qui est important, pour réduire les malentendus oraux." },
    '天相': { title:"Le bras droit digne et posé", story:"Tian Xiang dans le palais de la Carrière : vous tenez aux règles, excellez à épauler et à coordonner, fait pour être un bras droit précieux dans une organisation stable. Vous êtes consciencieux et digne de confiance. Le revers : un grand souci de l’avis des autres, et vous n’osez pas donner le vôtre.", fields:"Secrétariat, administration, ressources humaines, relations publiques, assistant juridique, gestion dans les services.", scenes:["Quand votre responsable est débordé, c’est à vous qu’il pense en premier pour l’aider.","En réunion, vous avez un avis différent, mais vous choisissez de vous taire."], advice:"À chaque réunion, exprimez au moins un point de vue personnel, pour que l’on voie ce que vous pensez." },
    '天梁': { title:"L’ancien qui protège tout le village", story:"Tian Liang dans le palais de la Carrière : responsable et protecteur, vous jouez souvent le rôle de celui qui règle les problèmes de tous, fait pour les métiers qui demandent expertise et confiance. {{B:天梁:Vous êtes respecté dans votre domaine d’expertise.|Vous vous faites souvent trop de souci pour les affaires des autres.}}", fields:"Santé, assurance, éducation, travail social, conseil, fonction publique.", scenes:["Quand un collègue a un souci, c’est vous qu’il vient consulter en premier.","Vous réglez le problème de quelqu’un d’autre, et votre propre travail prend du retard."], advice:"Avant d’aider, vérifiez où vous en êtes : c’est en prenant soin de vous que vous pouvez prendre soin des autres." },
    '七殺': { title:"Le général d’avant-garde qui ouvre la voie seul", story:"Qi Sha dans le palais de la Carrière : vous avez du cran et de l’élan, fait pour les métiers où l’on doit se débrouiller seul et ouvrir de nouvelles voies. Vous décidez vite et n’aimez pas être surveillé de trop près. Le revers : trop autoritaire, vous avez du mal à entendre l’avis des autres.", fields:"Création d’entreprise, développement commercial, armée et police, chirurgie, ingénierie, métiers du sport.", scenes:["Vous acceptez un dossier que personne n’ose toucher et obtenez des résultats en trois mois.","Votre responsable vous donne un conseil ; vous acquiescez, puis faites à votre manière."], advice:"Trouvez une personne de confiance qui vous serve de conseiller, et écoutez régulièrement d’autres voix." },
    '破軍': { title:"Celui qui abat le vieux mur pour bâtir du neuf", story:"Po Jun dans le palais de la Carrière : vous aimez le changement et le défi, fait pour les métiers qui demandent innovation et réforme. Votre carrière peut connaître de grands hauts et bas et de fréquents changements de voie, et chaque remise à zéro vous apprend quelque chose. Le revers : l’impulsivité et un manque de persévérance.", fields:"Création d’entreprise, jeunes pousses, recherche technologique, médias, projets de réforme.", scenes:["Dès votre première semaine dans l’entreprise, vous proposez trois réformes.","Après deux ans dans un poste, vous recommencez à penser à changer de voie."], advice:"Chaque fois que vous voulez partir, demandez-vous : qu’est-ce que je fuis, et qu’est-ce que je cherche ?" },
    '空': { title:"Une scène vide éclairée par une lumière empruntée", story:"Le palais de la Carrière n’a pas d’étoile majeure : pour lire votre carrière, on emprunte les étoiles du palais opposé, celui du Couple, et l’environnement, les responsables et les partenaires comptent particulièrement. L’avantage : une grande souplesse et une forte capacité d’adaptation, vous trouvez votre place dans des domaines variés. Le revers : une direction pas toujours claire.", fields:"Postes transversaux, travail en indépendant, missions par projet, entreprise familiale, associations d’affaires.", scenes:["Avec un nouveau bon responsable, vos résultats ont soudain fait un bond.","Vous avez peut-être travaillé dans trois secteurs totalement différents, en vous adaptant bien à chaque fois."], advice:"Choisissez activement les environnements et les partenaires qui vous font grandir, car ils influencent fortement votre direction." }
  }
};
